import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates an invoice with draft status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
});

test('createInvoice copies product data into line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[0].qty, 2);
});

test('createInvoice handles multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 3);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[1].qty, 10);
  assert.equal(r.value.lines[2].qty, 1);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for bad format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for invalid dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES for missing lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for invalid SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 2 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, linesCopy);
});

test('createInvoice handles leap year dates correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r2, { ok: false, error: 'DATE_INVALID' });
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  const r = lineTotal(line);
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles zero and large quantities', () => {
  const r1 = lineTotal({ qty: 0, unitPrice: 1000 });
  assert.equal(r1.ok, true);
  assert.equal(r1.value, 0);

  const r2 = lineTotal({ qty: 1000000, unitPrice: 5000000 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value, 5000000000000);
});

test('lineTotal reports LINE_INVALID for missing fields', () => {
  assert.deepEqual(lineTotal({ qty: 5 }), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal({ unitPrice: 8500 }), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal({}), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal(null), { ok: false, error: 'LINE_INVALID' });
});

test('lineTotal reports LINE_INVALID for non-numeric values', () => {
  assert.deepEqual(lineTotal({ qty: '5', unitPrice: 8500 }), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal({ qty: 5, unitPrice: '8500' }), { ok: false, error: 'LINE_INVALID' });
});

test('invoiceTotals calculates subtotal and total from lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 5 * 8500 = 42500
  // DEV-HOUR: 2 * 9500 = 19000
  // Total: 61500
  assert.equal(r.value.subtotal, 61500);
  assert.equal(r.value.total, 61500);
});

test('invoiceTotals handles single line item', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 120000);
  assert.equal(r.value.total, 120000);
});

test('invoiceTotals handles multiple line items with various quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 15 },
      { sku: 'COPY-HOUR', qty: 8 },
    ],
  }).value;

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // DES-HOUR: 10 * 8500 = 85000
  // DEV-HOUR: 15 * 9500 = 142500
  // COPY-HOUR: 8 * 6000 = 48000
  // Total: 275500
  assert.equal(r.value.subtotal, 275500);
  assert.equal(r.value.total, 275500);
});

test('invoiceTotals reports INVOICE_INVALID for missing lines', () => {
  assert.deepEqual(invoiceTotals({ customerId: 'C-001' }), { ok: false, error: 'INVOICE_INVALID' });
  assert.deepEqual(invoiceTotals(null), { ok: false, error: 'INVOICE_INVALID' });
  assert.deepEqual(invoiceTotals({}), { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals reports INVOICE_INVALID for non-array lines', () => {
  assert.deepEqual(invoiceTotals({ lines: 'not an array' }), { ok: false, error: 'INVOICE_INVALID' });
  assert.deepEqual(invoiceTotals({ lines: null }), { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals propagates LINE_INVALID from lineTotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ qty: 5 }],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'LINE_INVALID' });
});

test('invoiceTotals returns new object', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

